#include <bits/stdc++.h>
using namespace std;

class FFT {
public:
    struct Vector {
        int sz = 1 << 20;
        vector<long long> v;

        Vector(const vector<long long>& a) {
            v.resize(sz);
            for (size_t i = 0; i < a.size(); i++) {
                v[i] = a[i];
            }
        }

        vector<long long> FFT() {
            return DFT(0, 1, true);
        }

        vector<long long> FFT1() {
            vector<long long> x = DFT(0, 1, false);
            for (size_t i = 0; i < x.size(); i++) {
                x[i] = (x[i] * szinv) % mod;
            }
            return x;
        }

        vector<long long> DFT(int first, int pow, bool straight) {
            if (pow == sz) {
                return vector<long long>{v[first]};
            }
            vector<long long> zero = DFT(first, 2 * pow, straight);
            vector<long long> one = DFT(first + pow, 2 * pow, straight);
            int n = zero.size();
            vector<long long> ans(2 * n);
            for (int i = 0; i < n; i++) {
                long long val = (warr[i * pow] * one[i]) % mod;
                ans[i] = (zero[i] + val) % mod;
                long long val2 = (winvarr[i * pow] * one[i]) % mod;
                ans[n + i] = ((zero[i] - val2) % mod + mod) % mod;
            }
            return ans;
        }
    };

    vector<long long> fft(const vector<long long>& a) {
        vector<long long> ans(1 << 20, 0);
        long long wth = 1;
        for (size_t i = 0; i < ans.size(); i++) {
            long long x = 1;
            for (size_t j = 0; j < a.size(); j++) {
                ans[i] = (ans[i] + a[j] * x) % mod;
                x = (x * wth) % mod;
            }
            wth = (wth * w) % mod;
        }
        return ans;
    }

    vector<long long> pow(const vector<long long>& ans, int p) {
        vector<long long> res = ans;
        for (size_t i = 0; i < res.size(); i++) {
            res[i] = pow_mod(res[i], p);
        }
        return res;
    }

    long long pow_mod(long long x, int p) {
        long long result = 1;
        long long base = x % mod;
        while (p > 0) {
            if (p & 1) result = (result * base) % mod;
            base = (base * base) % mod;
            p >>= 1;
        }
        return result;
    }

    long long mod = 998244353;
    long long w = 646;
    long long winv;
    vector<long long> warr(1 << 20);
    vector<long long> winvarr(1 << 20);
