        vector<long long> x = fft(arr);
        x = pow(x, n / 2);
        Vector v(x);
        x = v.FFT1();
        long long ans = 0;
        for (size_t i = 0; i < x.size(); i++) {
            ans = (ans + x[i] * x[i]) % mod;
